/**
 * Semantic file-type icons — the CodeBuddy/VSCode "genie" file icon font
 * (seti-family glyphs). The woff is embedded as base64 and rendered via CSS
 * @font-face with the theme's per-type color — exactly how VSCode renders
 * file icons, so they look native. Pure presentation.
 * @module dsh-ide-ui/client/fileicons
 */

import { createElement } from 'react'

/**
 * Convert a CSS-escape glyph string ("\\E023") into the real Unicode
 * character (U+E023). Browsers never interpret CSS escapes inside React
 * text nodes — they only matter in CSS `content` — so the escape must be
 * decoded before rendering or the user sees literal "\E023" text.
 * Note: in a CSS escape the E is part of the hex codepoint (U+E023),
 * not a literal prefix.
 */
function glyphOf(esc: string): string {
  const m = /^\\([0-9A-Fa-f]{1,6})\s?$/.exec(esc)
  if (m && m[1]) return String.fromCharCode(parseInt(m[1], 16))
  return esc
}

const FONT_B64 = ""

const FONT_CSS = '@font-face{font-family:"dshide-fileicons";src:url(data:font/woff;base64,' + FONT_B64 + ') format("woff");font-weight:normal;font-style:normal;font-display:block}'

function injectFontCss() {
  if (typeof document === 'undefined') return
  if (document.querySelector('style[data-plugin-css="dsh-ide-ui/fileicons-font"]')) return
  const tag = document.createElement('style')
  tag.dataset.pluginCss = 'dsh-ide-ui/fileicons-font'
  tag.textContent = FONT_CSS
  document.head.appendChild(tag)
}
injectFontCss()

