/** Resolve the icon definition name for a file path. */
export function fileIconKey(path: string): string {
  const base = (path || '').split(/[\\/]/).pop() ?? ''
  const byName = NAME_MAP[base]
  if (byName) return byName
  const dot = base.lastIndexOf('.')
  if (dot > 0) {
    const ext = base.slice(dot + 1)
    const byExt = EXT_MAP[ext] ?? EXT_MAP[ext.toLowerCase()]
    if (byExt) return byExt
  }
  return '_default'
}

/** Render the semantic file icon for a path (CodeBuddy/VSCode genie font glyph). */
export function fileIcon(path: string, size = 16, className?: string): ReturnType<typeof createElement> | null {
  const key = fileIconKey(path)
  const def = ICONS[key] ?? ICONS._default ?? { c: '\\E00F', color: '' }
  const color = def.color || 'var(--dsw-alias-label-secondary)'
  return createElement('span', {
    className: className,
    style: {
      fontFamily: '"dshide-fileicons"',
      fontSize: size,
      lineHeight: 1,
      width: size,
      height: size,
      display: 'inline-block',
      flex: 'none',
      color,
      textAlign: 'center',
    },
    'aria-hidden': true,
  }, glyphOf(def.c))
}
